public static class LegacyRulesInstall {public static void Run(){var catalog=AssetDatabase.LoadAssetAtPath<TrainingMoveSet>("Assets/Shioka/調整Data/Fighter/Awari/Skill/Moves.asset");if(catalog.sharedLegacyRules!=null)throw new Exception("Already adopted");var rules=ScriptableObject.CreateInstance<LegacyBattleRules>();foreach(var field in typeof(LegacyBattleRuleValues).GetFields()){var old=typeof(TrainingMoveSet).GetProperty(field.Name).GetValue(catalog);field.SetValue(rules.values,old);}string dir="Assets/Shioka/調整Data/共通System/Compatibility";if(!AssetDatabase.IsValidFolder(dir))AssetDatabase.CreateFolder("Assets/Shioka/調整Data/共通System","Compatibility");AssetDatabase.CreateAsset(rules,dir+"/LegacyBattleRules.asset");catalog.sharedLegacyRules=rules;catalog.ClearAdoptedLegacyRules();foreach(var field in typeof(LegacyBattleRuleValues).GetFields())if(!Equals(field.GetValue(rules.values),typeof(TrainingMoveSet).GetProperty(field.Name).GetValue(catalog)))throw new Exception("Rule changed "+field.Name);EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssetIfDirty(catalog);Debug.Log("LEGACY_RULES9 values preserved; skill catalog now refs with inactive compatibility fields only");}}
